# Invoice finance: separate credit, dilution and limited seller recourse.
if(!exists('simulate_trade_receivables'))library(creditratingsystem)
trade_account_case<-function(template,amount){
 args<-template;origin<-'2023-04-01';end<-'2023-05-01';args$as_of<-origin;args$scenario_contract$dates<-list(end);args$baseline_cashflows<-list(list(scenario_id='s',cashflow_id='cash',date=end,amount=amount));args$exposure_paths<-list(list(scenario_id='s',exposure_id='account',date=end,signed_replacement_mark=0));args$collateral_paths<-list(list(scenario_id='s',netting_set_id='net',date=end,known_at=origin,collateral_value=0,haircut=0));args$settlement_terms[[1]]$estate_delay_days<-0;args$settlement_terms[[1]]$collateral_delay_days<-0;args$settlement_terms[[1]]$replacement_cost<-0;args$settlement_terms[[1]]$replacement_delay_days<-0;args$party_default_paths<-list(list(scenario_id='s',default_group_id='bank',date=end,conditional_pd=1,default_channel='bank'));args$shared_innovations<-list(list(scenario_id='s',date=end,channel_id='bank',uniform=.5));do.call(stress_pool_counterparties,args)$value
}
run_trade_receivable_products<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/trade_receivable_products.json',package='creditratingsystem'),simplifyVector=FALSE);out<-errors<-list()
 for(name in names(data$variants)){
 case<-data$variants[[name]];pool<-do.call(build_credit_asset_pool,case$pool_input)$value;borrowing<-do.call(receivables_borrowing_base,case$borrowing_input)$value;args<-case$simulation_input;args$invoice_pool<-pool;paths<-do.call(simulate_trade_receivables,args)$value;losses<-vapply(paths$ending_states,function(r)r$net_credit_loss+r$net_dilution_loss+r$commingling_loss+r$workout_and_replacement_cost,numeric(1));distribution<-credit_loss_distribution(losses,rep(.25,4),scenario_ids=c('s','t','u','v'),levels=c(.5,.95),currency='EUR')$value;account<-trade_account_case(data$account_stress_template,paths$ending_states[[4]]$net_investor_cash);target<-list(event='net_investor_shortfall',horizon=90,time_unit='days',probability_measure='PHYSICAL',conditioning='PIT');subject<-list(subject_id=paste0(name,'-pool'),subject_type='portfolio');components<-list(c(list(component_id=paste0(name,'-el'),quantity='EL',value=distribution$expected_loss,currency='EUR'),subject,list(variant='credit_dilution_and_operating_cost',definition=target)));binding<-list(profile_id=name,profile_version='1',model_id='invoice-finance',model_version='1',model_hash=paths$sha256,input_hash=pool$sha256);assessment<-compose_risk_assessment(paste0(name,'-assessment'),subject,components,binding,pool$as_of,pool$as_of,pool$as_of)$value
 wrong<-args;if(name=='recourse')wrong$seller_terms[[1]]$settlement_date<-'2023-01-01'else if(name=='nonrecourse')wrong$invoice_scenarios[[1]]$payment_date<-'2024-01-01'else wrong$party_mapping<-c(wrong$party_mapping,list(wrong$party_mapping[[1]]));error<-tryCatch(do.call(simulate_trade_receivables,wrong),error=identity);stopifnot(inherits(error,'creditratingsystem_error'));errors[[name]]<-error$code;out[[name]]<-list(pool=pool,borrowing_base=borrowing,paths=paths,distribution=distribution,account_stress=account,assessment=assessment)
 }
 if(verify_reference){same<-function(a,b)stopifnot(is.finite(a),abs(a-b)<=1e-10+1e-12*abs(b));expected<-list(recourse=list(losses=c(30,40,20,0),bb=40),nonrecourse=list(losses=c(60,60,20,0),bb=35),invoice_pool=list(losses=c(70,100,40,0),bb=85));for(name in names(out)){r<-out[[name]];e<-expected[[name]];for(i in seq_along(e$losses))same(r$distribution$loss_paths[[i]],e$losses[[i]]);same(r$distribution$expected_loss,mean(e$losses));same(r$borrowing_base$borrowing_base,e$bb);same(r$paths$ending_states[[3]]$net_credit_loss,0);stopifnot(!any(vapply(Filter(function(i)i$scenario_id=='u',r$paths$invoice_results),function(i)i$debtor_credit_event,logical(1))),r$assessment$composition_status=='CONSISTENT');same(r$account_stress$ending_states[[1]]$credit_loss,if(name=='invoice_pool')100 else 50);stopifnot(errors[[name]]==if(name=='invoice_pool')'STRUCTURED_DEFAULT_GROUP'else'STRUCTURED_CALENDAR')};stopifnot(all(vapply(out$nonrecourse$paths$seller_results,function(s)s$aggregate_payment==0,logical(1))))}
 list(data_origin=data$data_origin,version=data$version,product=data$product,variants=out,contract_error_codes=errors)
}
